import * as React from "react";
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'

import "../scss/main.scss";

import Header from "../components/Header";
import Footer from "../components/Footer";
import AccentDots from "../components/AccentDots";
import gridColours from "../data/grid-colours.json";

interface PageProps {
  data: {
    shuffleCards: {
      nodes: {
        childImageSharp: {
          thumb: IGatsbyImageData
          original: { width: number; height: number }
        }
      }[]
    }
    mosaicCard: {
      nodes: {
        childImageSharp: {
          thumb: IGatsbyImageData
        }
      }[]
    }
  }
}

// Card background for Bird Shuffle — bird photo split into a shuffled 3x3 tile grid
const SHUFFLE_ORDER = [2, 7, 4, 6, 0, 8, 1, 5, 3] // fixed shuffle so it looks good

const BirdShuffleCardBg: React.FC<{ imageSrc: string }> = ({ imageSrc }) => (
  <div className="shuffle-card-bg">
    {SHUFFLE_ORDER.map((tileValue, i) => {
      const col = tileValue % 3
      const row = Math.floor(tileValue / 3)
      return (
        <div
          key={i}
          className="shuffle-card-bg__tile"
          style={{
            backgroundImage: `url(${imageSrc})`,
            backgroundSize: '300% 300%',
            backgroundPosition: `${col * 50}% ${row * 50}%`,
          }}
        />
      )
    })}
  </div>
)

// Card background for Circle Memory — 5x5 grid of coloured dots
const CircleMemoryCardBg: React.FC = () => {
  const [dots, setDots] = React.useState<(string | null)[]>(
    () => Array.from({ length: 25 }, () => null)
  )

  React.useEffect(() => {
    const shuffled = [...gridColours]
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
    }
    // 25 cells, some filled some empty
    setDots(
      Array.from({ length: 25 }, (_, i) =>
        i < 10 ? shuffled[i % shuffled.length] : null
      ).sort(() => Math.random() - 0.5)
    )
  }, [])

  return (
    <div className="circle-memory-card-bg">
      {dots.map((colour, i) => (
        <div
          key={i}
          className="circle-memory-card-bg__dot"
          style={colour
            ? { '--dot-colour': colour } as React.CSSProperties
            : { opacity: 0.15, background: '#1E3A5F' }
          }
        />
      ))}
    </div>
  )
}

// Card background for Bird Draw — a bird photo
const STROKE_COLOURS = ['#FF6B6B', '#4ECDC4', '#A78BFA', '#FFD93D', '#FF8C42']
const STROKE_BLENDS: GlobalCompositeOperation[] = [
  'multiply', 'screen', 'overlay', 'color-dodge', 'color-burn',
  'hard-light', 'soft-light', 'difference', 'exclusion', 'luminosity',
]

const BirdDrawCardBg: React.FC<{ imageSrc: string }> = ({ imageSrc }) => {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)

  React.useEffect(() => {
    if (!imageSrc || !canvasRef.current) return
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const img = new Image()
    img.crossOrigin = 'anonymous'
    img.onload = () => {
      const size = 400
      canvas.width = size
      canvas.height = size

      // Draw base photo (cover fit)
      const ratio = Math.max(size / img.naturalWidth, size / img.naturalHeight)
      const w = img.naturalWidth * ratio
      const h = img.naturalHeight * ratio
      const ox = (size - w) / 2
      const oy = (size - h) / 2
      ctx.drawImage(img, ox, oy, w, h)

      // Edge detection — only keep the strongest edges
      const imageData = ctx.getImageData(0, 0, size, size)
      const pixels = imageData.data
      const lum = (i: number) => pixels[i] * 0.299 + pixels[i + 1] * 0.587 + pixels[i + 2] * 0.114
      const edges: { x: number; y: number }[] = []
      const step = 4

      for (let y = step; y < size - step; y += step) {
        for (let x = step; x < size - step; x += step) {
          const i = (y * size + x) * 4
          const l = lum(i)
          const lr = lum((y * size + x + step) * 4)
          const ld = lum(((y + step) * size + x) * 4)
          const diff = Math.abs(l - lr) + Math.abs(l - ld)
          if (diff > 60) {
            edges.push({ x, y })
          }
        }
      }

      // Pick edge points as loose anchors for expressive sweeping strokes
      const shuffled = edges.sort(() => Math.random() - 0.5)
      const anchors = shuffled.slice(0, Math.min(edges.length, 120))

      // Also scatter some random background points for marks that aren't on edges
      for (let i = 0; i < 30; i++) {
        anchors.push({ x: Math.random() * size, y: Math.random() * size })
      }

      // Shuffle everything together
      anchors.sort(() => Math.random() - 0.5)

      const pickBlend = () => STROKE_BLENDS[Math.floor(Math.random() * STROKE_BLENDS.length)]
      const pickColour = () => STROKE_COLOURS[Math.floor(Math.random() * STROKE_COLOURS.length)]

      // Colour washes — 1 or 2 large blocks as a base layer
      const washCount = 1 + Math.floor(Math.random() * 2)
      for (let i = 0; i < washCount; i++) {
        const wx = -size * 0.2 + Math.random() * size * 0.6
        const wy = -size * 0.2 + Math.random() * size * 0.6
        const ww = size * 0.4 + Math.random() * size * 0.5
        const wh = size * 0.4 + Math.random() * size * 0.5

        ctx.save()
        ctx.globalCompositeOperation = pickBlend()
        ctx.globalAlpha = 0.15 + Math.random() * 0.3
        ctx.fillStyle = pickColour()
        ctx.fillRect(wx, wy, ww, wh)
        ctx.restore()
      }

      // Big sweeping curves — 10 to 15 gestural strokes, some very bold
      const strokeCount = 10 + Math.floor(Math.random() * 6)
      const perStroke = Math.floor(anchors.length / strokeCount)

      for (let i = 0; i < strokeCount; i++) {
        const pts = anchors.slice(i * perStroke, (i + 1) * perStroke)
        if (pts.length < 3) continue

        const cx = size / 2, cy = size / 2
        pts.sort((a, b) => Math.atan2(a.y - cy, a.x - cx) - Math.atan2(b.y - cy, b.x - cx))

        const start = Math.floor(Math.random() * pts.length * 0.3)
        const len = 4 + Math.floor(Math.random() * (pts.length * 0.6))
        const curve = pts.slice(start, start + len)
        if (curve.length < 3) continue

        ctx.save()
        ctx.globalCompositeOperation = pickBlend()
        ctx.globalAlpha = 0.15 + Math.random() * 0.55
        ctx.strokeStyle = pickColour()
        ctx.lineWidth = 1 + Math.random() * 14
        ctx.lineCap = 'round'
        ctx.lineJoin = 'round'

        ctx.beginPath()
        ctx.moveTo(curve[0].x, curve[0].y)
        for (let j = 1; j < curve.length - 1; j++) {
          const mx = (curve[j].x + curve[j + 1].x) / 2
          const my = (curve[j].y + curve[j + 1].y) / 2
          ctx.quadraticCurveTo(curve[j].x, curve[j].y, mx, my)
        }
        ctx.lineTo(curve[curve.length - 1].x, curve[curve.length - 1].y)
        ctx.stroke()
        ctx.restore()
      }

      // Bold straight lines — 3 to 6 sweeping across the canvas
      const lineCount = 3 + Math.floor(Math.random() * 4)
      for (let i = 0; i < lineCount; i++) {
        const x1 = Math.random() * size
        const y1 = Math.random() * size
        const angle = Math.random() * Math.PI * 2
        const len = 120 + Math.random() * 250
        const x2 = x1 + Math.cos(angle) * len
        const y2 = y1 + Math.sin(angle) * len

        ctx.save()
        ctx.globalCompositeOperation = pickBlend()
        ctx.globalAlpha = 0.2 + Math.random() * 0.5
        ctx.strokeStyle = pickColour()
        ctx.lineWidth = 2 + Math.random() * 10
        ctx.lineCap = 'round'

        ctx.beginPath()
        ctx.moveTo(x1, y1)
        ctx.lineTo(x2, y2)
        ctx.stroke()
        ctx.restore()
      }

      // Solid circles — 2 or 3
      const shapeCount = 2 + Math.floor(Math.random() * 2)
      for (let i = 0; i < shapeCount; i++) {
        const ccx = size * 0.15 + Math.random() * size * 0.7
        const ccy = size * 0.15 + Math.random() * size * 0.7
        const r = 30 + Math.random() * 90

        ctx.save()
        ctx.globalCompositeOperation = pickBlend()
        ctx.globalAlpha = 0.15 + Math.random() * 0.4
        ctx.fillStyle = pickColour()
        ctx.beginPath()
        ctx.arc(ccx, ccy, r, 0, Math.PI * 2)
        ctx.fill()
        ctx.restore()
      }

      // Scattered dots — tiny solid circles
      const dotCount = 15 + Math.floor(Math.random() * 20)
      for (let i = 0; i < dotCount; i++) {
        const dx = Math.random() * size
        const dy = Math.random() * size
        const dr = 2 + Math.random() * 5

        ctx.save()
        ctx.globalCompositeOperation = pickBlend()
        ctx.globalAlpha = 0.3 + Math.random() * 0.6
        ctx.fillStyle = pickColour()
        ctx.beginPath()
        ctx.arc(dx, dy, dr, 0, Math.PI * 2)
        ctx.fill()
        ctx.restore()
      }

      // Quick flicks and dashes
      const flickCount = 6 + Math.floor(Math.random() * 8)
      for (let i = 0; i < flickCount; i++) {
        const p = anchors[Math.floor(Math.random() * anchors.length)]
        const angle = Math.random() * Math.PI * 2
        const len = 20 + Math.random() * 60

        ctx.save()
        ctx.globalCompositeOperation = pickBlend()
        ctx.globalAlpha = 0.25 + Math.random() * 0.5
        ctx.strokeStyle = pickColour()
        ctx.lineWidth = 0.5 + Math.random() * 4
        ctx.lineCap = 'round'

        ctx.beginPath()
        ctx.moveTo(p.x, p.y)
        ctx.lineTo(p.x + Math.cos(angle) * len, p.y + Math.sin(angle) * len)
        ctx.stroke()
        ctx.restore()
      }
    }
    img.src = imageSrc
  }, [imageSrc])

  return <canvas ref={canvasRef} className="bird-draw-card-bg" />
}

const DeveloperPage: React.FC<PageProps> = ({ data }) => {
  // Pick random bird photos for cards (deferred to avoid SSR mismatch)
  const [shuffleCardSrc, setShuffleCardSrc] = React.useState('')
  const [birdDrawCardSrc, setBirdDrawCardSrc] = React.useState('')

  React.useEffect(() => {
    const portraits = data.shuffleCards.nodes.filter(n => {
      const { width, height } = n.childImageSharp.original
      return height >= width
    })
    const pool = portraits.length > 0 ? portraits : data.shuffleCards.nodes
    const pick = pool[Math.floor(Math.random() * pool.length)]
    const image = pick ? getImage(pick.childImageSharp.thumb) : null
    setShuffleCardSrc(image?.images?.fallback?.src || '')

    // Pick a different random photo for Bird Draw card
    const drawPick = data.shuffleCards.nodes[Math.floor(Math.random() * data.shuffleCards.nodes.length)]
    const drawImage = drawPick ? getImage(drawPick.childImageSharp.thumb) : null
    setBirdDrawCardSrc(drawImage?.images?.fallback?.src || '')
  }, [data.shuffleCards.nodes])

  const mosaicCardImage = data.mosaicCard.nodes[0]
    ? getImage(data.mosaicCard.nodes[0].childImageSharp.thumb)
    : null

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <h1>Code</h1>
        <p>Playful experiments &mdash; bringing creative ideas to life with code.</p>
        <AccentDots />
      </div>
      <div className="galleries-container">
        <div className="galleries-grid">
          <Link to="/bird-shuffle" className="gallery-card">
            <BirdShuffleCardBg imageSrc={shuffleCardSrc} />
            <div className="gallery-info">
              <h2>Bird Shuffle</h2>
              <p>Shuffle the tiles, discover the bird</p>
            </div>
          </Link>
          <Link to="/bird-mosaic" className="gallery-card gallery-card--hide-mobile">
            {mosaicCardImage && (
              <GatsbyImage
                image={mosaicCardImage}
                alt="Bird Mosaic"
                className="gallery-cover gallery-cover--mosaic"
              />
            )}
            <div className="gallery-info">
              <h2>Bird Mosaic</h2>
              <p>Photos arranged into a bird silhouette</p>
            </div>
          </Link>
          <Link to="/circle-memory" className="gallery-card">
            <CircleMemoryCardBg />
            <div className="gallery-info">
              <h2>Circle Memory</h2>
              <p>A colour sequence memory game</p>
            </div>
          </Link>
          <Link to="/bird-draw" className="gallery-card">
            <BirdDrawCardBg imageSrc={birdDrawCardSrc} />
            <div className="gallery-info">
              <h2>Bird Draw</h2>
              <p>Draw over photographs</p>
            </div>
          </Link>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export const pageQuery = graphql`
  query DeveloperImagesQuery {
    shuffleCards: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        extension: { regex: "/(jpg|jpeg|png)/" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(
            width: 400
            height: 400
            placeholder: BLURRED
            transformOptions: { cropFocus: ATTENTION }
          )
          original { width height }
        }
      }
    }
    mosaicCard: allFile(
      filter: {
        sourceInstanceName: { eq: "photography" }
        name: { eq: "mosaicCard" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(
            width: 400
            placeholder: BLURRED
          )
        }
      }
    }
  }
`

export default DeveloperPage;
